      expectedOutput: "const x = 2;",
      goal: "Resolve merge conflict markers in provided file text.",
      starter: "```ts\nexport function resolveConflict(raw: string): string {\n  void raw;\n  return '';\n}\n```",
      solution: "```ts\nexport function resolveConflict(raw: string): string {\n  const m = raw.match(/=======\\r?\\n([\\s\\S]*?)\\r?\\n>>>>>>>/);\n  return (m?.[1] ?? '').trim();\n}\n```",
